function validate([nums, freq]) {
  if (!Array.isArray(nums) || !Array.isArray(freq) || nums.length !== freq.length) return 'nums and freq must have the same length.';
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each ID in nums is an integer from 1 to 10^5.';
  if (freq.some(v => !Number.isInteger(v) || v === 0 || v < -100000 || v > 100000)) return 'Each freq value is a non-zero integer from -10^5 to 10^5.';
  const count = new Map();
  for (let i = 0; i < nums.length; i++) {
    const next = (count.get(nums[i]) ?? 0) + freq[i];
    if (next < 0) return `Step ${i} takes out more copies of ID ${nums[i]} than the collection holds.`;
    count.set(nums[i], next);
  }
  return null;
}

