function mostFrequentIDs(nums, freq) {
  const count = new Map();
  const heap = [];
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] >= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let largest = parent;
      if (left < heap.length && heap[left][0] > heap[largest][0]) largest = left;
      if (right < heap.length && heap[right][0] > heap[largest][0]) largest = right;
      if (largest === parent) break;
      [heap[parent], heap[largest]] = [heap[largest], heap[parent]];
      parent = largest;
    }
  };

  const ans = [];
  for (let i = 0; i < nums.length; i++) {
    const id = nums[i];
    const current = (count.get(id) ?? 0) + freq[i];
    count.set(id, current);
    push([current, id]);
    while (count.get(heap[0][1]) !== heap[0][0]) {
      pop();
    }
    ans.push(heap[0][0]);
  }
  return ans;
}

