function mostFrequentIDs(nums, freq) {
  const totals = new Map();
  const result = [];
  for (let step = 0; step < nums.length; step++) {
    totals.set(nums[step], (totals.get(nums[step]) || 0) + freq[step]);
    let most = 0;
    for (const total of totals.values()) most = Math.max(most, total);
    result.push(most);
  }
  return result;
}

