function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  const poolSize = large ? [3, 50, 1000][int(0, 2)] : int(1, 4);
  const spread = [poolSize, 100, 100000][int(0, 2)];
  const pool = Array.from({ length: poolSize }, () => int(1, Math.max(spread, poolSize)));
  const amountTop = large ? [100000, 1000, 10][int(0, 2)] : [3, 10, 100000][int(0, 2)];
  const count = new Map();
  const nums = [], freq = [];
  for (let i = 0; i < n; i++) {
    const id = pool[int(0, poolSize - 1)];
    const have = count.get(id) ?? 0;
    let change;
    // Removals never exceed what the collection holds, as the problem guarantees.
    if (have > 0 && rand() < 0.45) change = -(rand() < 0.4 ? Math.min(have, 100000) : int(1, Math.min(have, 100000)));
    else change = int(1, amountTop);
    count.set(id, have + change);
    nums.push(id);
    freq.push(change);
  }
  return [nums, freq];
}
